<?php
namespace Tests\Feature;
use App\Models\{User,Budget,Expense}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class BudgetManagementTest extends TestCase { use RefreshDatabase; private function user(){return User::factory()->create(['role'=>'admin']);} private function data(){return ['name'=>'Marketing','period_type'=>'monthly','category'=>'Ads','amount'=>'1000.00','period_start'=>'2026-01-01','period_end'=>'2026-01-31'];} public function test_budget_crud_works(): void {$user=$this->user();$this->actingAs($user)->post(route('budgets.store'),$this->data())->assertRedirect(route('budgets.index'));$budget=Budget::first();$this->assertSame('Marketing',$budget->name);$this->actingAs($user)->put(route('budgets.update',$budget),array_merge($this->data(),['name'=>'Updated']))->assertRedirect(route('budgets.show',$budget));$this->assertDatabaseHas('budgets',['id'=>$budget->id,'name'=>'Updated']);$this->actingAs($user)->delete(route('budgets.destroy',$budget))->assertRedirect(route('budgets.index'));$this->assertDatabaseMissing('budgets',['id'=>$budget->id]);} public function test_expense_is_linked_and_tracking_is_decimal_and_over_budget(): void {$user=$this->user();$budget=Budget::create(array_merge($this->data(),['amount'=>'100.00']));$this->actingAs($user)->post(route('expenses.store'),['budget_id'=>$budget->id,'amount'=>'80.00','expense_date'=>'2026-01-15','description'=>'Ads','category'=>'Ads'])->assertRedirect(route('budgets.show',$budget));$this->actingAs($user)->post(route('expenses.store'),['budget_id'=>$budget->id,'amount'=>'30.00','expense_date'=>'2026-01-16','description'=>'More Ads','category'=>'Ads']);$this->assertDatabaseHas('expenses',['budget_id'=>$budget->id,'amount'=>'30.00']);$this->assertSame('110.00',(new \App\Services\BudgetTracker)->summarize($budget->fresh('expenses'))['used']);$this->assertSame('Over budget',(new \App\Services\BudgetTracker)->summarize($budget->fresh('expenses'))['status']);} public function test_expense_outside_period_is_rejected(): void {$user=$this->user();$budget=Budget::create($this->data());$this->actingAs($user)->post(route('expenses.store'),['budget_id'=>$budget->id,'amount'=>'10','expense_date'=>'2026-02-01','description'=>'Invalid','category'=>'Ads'])->assertSessionHasErrors('expense_date');$this->assertDatabaseCount('expenses',0);} }
